<?php
declare(strict_types=1);

final class EnvironmentWriter
{
    public static function write(string $file, array $values): void
    {
        $lines = [
            '# Generated by 2CAM Property Hub installer',
            '# Do not expose this file through the web server.',
        ];
        foreach ($values as $key => $value) {
            if (!preg_match('/^[A-Z0-9_]+$/', (string)$key)) continue;
            $lines[] = $key.'='.self::quote((string)$value);
        }
        $contents = implode(PHP_EOL, $lines).PHP_EOL;
        $tmp = $file.'.tmp.'.bin2hex(random_bytes(4));
        if (file_put_contents($tmp, $contents, LOCK_EX) === false) {
            throw new RuntimeException('No fue posible escribir el archivo temporal de configuración.');
        }
        @chmod($tmp, 0600);
        if (!@rename($tmp, $file)) {
            @unlink($tmp);
            throw new RuntimeException('No fue posible activar el archivo .env.');
        }
    }

    private static function quote(string $value): string
    {
        if ($value === '') return '""';
        if (preg_match('/^[A-Za-z0-9_\.\-:\/]+$/', $value)) return $value;
        return '"'.str_replace(['\\','"',"\r","\n"], ['\\\\','\\"','','\\n'], $value).'"';
    }
}
